/**
 * Kruitbosch Detail Service — Fetches enriched product detail data from kruitbosch_products table.
 *
 * Returns fields not exposed in the unified SupplierOffer shape:
 * - color (nullable)
 * - vatRateBasisPoints
 * - fullDescription (nullable, maps to description column)
 */

import { eq } from 'drizzle-orm'
import { db } from '@/db/index.js'
import { kruitboschProducts } from '@/db/schema.js'

/** Enriched Kruitbosch product detail response shape */
export interface KruitboschDetailResponse {
  eanUpc: string
  color: string | null
  vatRateBasisPoints: number
  fullDescription: string | null
}

/**
 * Fetch detailed product information for a Kruitbosch product by EAN.
 * Returns null if the product is not found in the local catalog.
 */
export async function getKruitboschDetail(ean: string): Promise<KruitboschDetailResponse | null> {
  const trimmedEan = ean.trim()

  const results = await db.select({
    eanUpc: kruitboschProducts.eanUpc,
    color: kruitboschProducts.color,
    vatRateBasisPoints: kruitboschProducts.vatRateBasisPoints,
    fullDescription: kruitboschProducts.description,
  })
    .from(kruitboschProducts)
    .where(eq(kruitboschProducts.eanUpc, trimmedEan))

  if (results.length === 0) {
    return null
  }

  const row = results[0]

  return {
    eanUpc: row.eanUpc,
    color: row.color ?? null,
    vatRateBasisPoints: row.vatRateBasisPoints,
    fullDescription: row.fullDescription ?? null,
  }
}

/**
 * Gransier Detail Service — Fetches enriched product detail data from gransier_products table.
 *
 * Returns fields not exposed in the unified SupplierOffer shape:
 * - color (nullable)
 * - vatRateBasisPoints
 * - fullDescription (nullable, maps to description column)
 */

import { eq } from 'drizzle-orm'
import { db } from '@/db/index.js'
import { gransierProducts } from '@/db/schema.js'

/** Enriched Gransier product detail response shape */
export interface GransierDetailResponse {
  eanUpc: string
  color: string | null
  vatRateBasisPoints: number
  fullDescription: string | null
}

/**
 * Fetch detailed product information for a Gransier product by EAN.
 * Returns null if the product is not found in the local catalog.
 */
export async function getGransierDetail(ean: string): Promise<GransierDetailResponse | null> {
  const trimmedEan = ean.trim()

  const results = await db.select({
    eanUpc: gransierProducts.eanUpc,
    color: gransierProducts.color,
    vatRateBasisPoints: gransierProducts.vatRateBasisPoints,
    fullDescription: gransierProducts.description,
  })
    .from(gransierProducts)
    .where(eq(gransierProducts.eanUpc, trimmedEan))

  if (results.length === 0) {
    return null
  }

  const row = results[0]

  return {
    eanUpc: row.eanUpc,
    color: row.color ?? null,
    vatRateBasisPoints: row.vatRateBasisPoints,
    fullDescription: row.fullDescription ?? null,
  }
}

/**
 * Product Finder — Frontend types.
 */

export interface SupplierOffer {
  eanUpc: string
  itemNumber: string
  brand?: string
  model?: string
  /** Product description (used as fallback when model is empty) */
  description?: string
  name?: string
  imageUrl?: string
  recommendedRetailPriceGross?: number
  grossPurchasePriceGross?: number
  suggestedSellPriceNet?: number
  suggestedCostPriceNet?: number
  supplierName: string
  lang?: string
  /** Product category */
  category?: string
}

export interface PaginationInfo {
  page: number
  pageSize: number
  totalPages: number
  totalElements: number
}

export interface SearchResults {
  offers: SupplierOffer[]
  pagination?: PaginationInfo
}

export interface AuthStatus {
  authenticated: boolean
  expiresAt: number | null
}

/** Freshness status computed from lastSyncedAt timestamp */
export type SupplierFreshness = 'ok' | 'stale' | 'failed'

/** Extended supplier info returned by GET /suppliers endpoint */
export interface SupplierInfo {
  id: string
  name: string
  enabled: boolean
  lastSyncedAt?: string | null
  status?: SupplierFreshness
  authStatus?: AuthStatus
}

export interface ImportRequest {
  eanUpc: string
  name: string
  sellPrice: number
  costPrice: number
  supplierName: string
  /** Initial stock quantity — defaults to 0 if not provided */
  quantityOnHand?: number
}

export interface ImportResult {
  success: boolean
  partId?: string
  action: 'created' | 'updated'
  message: string
}

// ── Detail view types ─────────────────────────────────────────────────────

/** Enriched product detail returned by per-supplier detail endpoints */
export interface ProductDetail {
  eanUpc: string
  status?: 'ACTIVE' | 'OBSOLETE'
  minimumOrderAmount?: number
  unitsInPackaging?: number
  netWeight?: number | null
  grossWeight?: number | null
  keywordDescription?: string
  productGroupDescription?: string
  vatRate?: string
  longDescription?: string
  color?: string | null
  vatRateBasisPoints?: number
  fullDescription?: string | null
  category?: string | null
  _cacheVersion?: 'nested' | 'flat'
}

/** Field definition for rendering a detail card */
export interface DetailFieldConfig {
  /** Key in the ProductDetail object */
  key: keyof ProductDetail
  /** Human-readable label shown above the value */
  label: string
  /** CSS class override for the value display (e.g. 'badge', 'price-highlight') */
  variant?: 'default' | 'badge' | 'price-highlight' | 'weight'
  /** Custom render function — overrides default rendering */
  render?: (value: unknown, detail: ProductDetail) => React.ReactNode
  /** Whether this field should only show when it has a non-null/non-empty value */
  conditional?: boolean
}

/**
 * DetailCardGrid — Renders product detail data as a structured card grid.
 *
 * Supports visual hierarchy: status badges, price highlights, weight values,
 * and plain-text descriptions. Fields are configured via a props array for
 * flexible layout control.
 */

import type { ProductDetail, DetailFieldConfig } from '../types.js'

interface DetailCardGridProps {
  /** The product detail data to render */
  detail: ProductDetail
  /** Field configuration defining which fields to show and how */
  fields: DetailFieldConfig[]
}

export function DetailCardGrid({ detail, fields }: DetailCardGridProps) {
  if (fields.length === 0) return null

  const getValue = (field: DetailFieldConfig): unknown => {
    return (detail as unknown as Record<string, unknown>)[field.key]
  }

  const shouldShow = (value: unknown, fieldConfig: DetailFieldConfig): boolean => {
    if (!fieldConfig.conditional) return true
    // Show only when value is non-null and non-empty
    if (value == null) return false
    if (typeof value === 'string' && value.trim() === '') return false
    if (typeof value === 'number' && isNaN(value)) return false
    return true
  }

  const renderValue = (field: DetailFieldConfig, value: unknown): React.ReactNode => {
    // Custom render function takes priority
    if (field.render) {
      return field.render(value, detail)
    }

    // Default rendering based on variant
    switch (field.variant) {
      case 'badge':
        return (
          <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
            {String(value)}
          </span>
        )

      case 'price-highlight': {
        const num = typeof value === 'number' ? value : parseFloat(String(value))
        if (isNaN(num)) return String(value) || '—'
        return <span className="text-lg font-bold text-green-700">€{num.toFixed(2)}</span>
      }

      case 'weight': {
        const num = typeof value === 'number' ? value : parseFloat(String(value))
        if (isNaN(num)) return String(value) || '—'
        return <span className="text-sm font-medium">{num} kg</span>
      }

      default:
        // Plain text for descriptions and regular fields
        if (value == null) return <span className="text-muted-foreground">—</span>
        if (typeof value === 'string') {
          return <p className="leading-relaxed">{value}</p>
        }
        return String(value)
    }
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4" role="region">
      {fields.map(field => {
        const value = getValue(field)
        if (!shouldShow(value, field)) return null

        return (
          <div
            key={String(field.key)}
            className="bg-card border rounded-lg p-3 shadow-sm"
            role="region"
            aria-label={field.label}
          >
            <dt className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-1">
              {field.label}
            </dt>
            <dd className="mt-0.5">
              {renderValue(field, value)}
            </dd>
          </div>
        )
      })}
    </div>
  )
}

/**
 * Product Finder Routes — Per-supplier search, combined search, and import endpoints.
 *
 * GET  /product-finder/search?ean=XXX&supplier=dst          — EAN search for specific supplier
 * GET  /product-finder/search?q=keyword&supplier=kruitbosch — Keyword search for specific supplier
 * GET  /product-finder/search/all?ean=XXX                   — Search all suppliers (combined)
 * POST /product-finder/sync/:supplier                       — Sync catalog from a supplier
 * POST /product-finder/import                               — Import product into local catalog
 * GET  /product-finder/suppliers                            — List available suppliers
 */

import { Hono } from 'hono'
import {
  searchSupplierByEan,
  searchSupplierByKeyword,
  searchAllByEan,
  searchAllByKeyword,
  syncSupplier,
  getAuthStatus
} from '../features/product-finder/services/search-service.js'
import { importProduct } from '../features/product-finder/services/import-service.js'
import { getSupplierList } from '../features/product-finder/services/suppliers/index.js'
import { getDstDetail } from '../features/product-finder/services/suppliers/dst/detail-service.js'
import { getKruitboschDetail } from '../features/product-finder/services/suppliers/kruitbosch/detail-service.js'
import { getGransierDetail } from '../features/product-finder/services/suppliers/gransier/detail-service.js'

// ============================================================================
// GET /search — Per-supplier search (EAN or keyword)
// ============================================================================

const productFinderRoutes = new Hono()

productFinderRoutes.get('/search', async (c) => {
  const ean = c.req.query('ean')
  const q = c.req.query('q')
  const supplier = c.req.query('supplier') || 'dst' // default to dst for backward compat
  const page = parseInt(c.req.query('page') || '0', 10)
  const size = parseInt(c.req.query('size') || '20', 10)

  if (!ean && !q) {
    return c.json({ error: 'Provide either "ean" (exact match) or "q" (keyword search)' }, 400)
  }

  try {
    let result

    if (ean) {
      result = await searchSupplierByEan(supplier, ean)
    } else {
      result = await searchSupplierByKeyword(supplier, q!, page, size)
    }

    return c.json(result)
  } catch (err) {
    console.error('[GET /product-finder/search] Error:', err instanceof Error ? err.message : String(err))
    const status = getAuthStatus()
    if (!status.authenticated) {
      return c.json({ error: 'Not authenticated. Please log in to DST first.', offers: [] }, 401)
    }
    return c.json({ error: 'Search failed', offers: [], pagination: null }, 500)
  }
})

// ============================================================================
// GET /search/all — Combined search across all suppliers
// ============================================================================

productFinderRoutes.get('/search/all', async (c) => {
  const ean = c.req.query('ean')
  const q = c.req.query('q')
  const page = parseInt(c.req.query('page') || '0', 10)
  const size = parseInt(c.req.query('size') || '20', 10)

  if (!ean && !q) {
    return c.json({ error: 'Provide either "ean" (exact match) or "q" (keyword search)' }, 400)
  }

  try {
    let result

    if (ean) {
      result = await searchAllByEan(ean)
    } else {
      result = await searchAllByKeyword(q!, page, size)
    }

    return c.json(result)
  } catch (err) {
    console.error('[GET /product-finder/search/all] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Search failed', offers: [], pagination: null }, 500)
  }
})

// ============================================================================
// POST /sync/:supplier — Sync catalog from a supplier (e.g. Kruitbosch)
// ============================================================================

productFinderRoutes.post('/sync/:supplier', async (c) => {
  const supplierId = c.req.param('supplier')

  try {
    const result = await syncSupplier(supplierId)
    return c.json(result)
  } catch (err) {
    console.error(`[POST /product-finder/sync/${supplierId}] Error:`, err instanceof Error ? err.message : String(err))
    return c.json({ success: false, importedCount: 0, error: err instanceof Error ? err.message : 'Unknown error' }, 500)
  }
})

// ============================================================================
// GET /suppliers — List available suppliers (async, includes sync status)
// ============================================================================

productFinderRoutes.get('/suppliers', async (c) => {
  const list = await getSupplierList()
  return c.json({ suppliers: list })
})

// ============================================================================
// POST /import — Import product into local catalog
// ============================================================================

interface ImportRequest {
  eanUpc: string
  name: string
  sellPrice: number
  costPrice: number
  supplierName: string
  quantityOnHand?: number
}

productFinderRoutes.post('/import', async (c) => {
  try {
    const body = await c.req.json() as ImportRequest

    if (!body.eanUpc || !body.name || body.sellPrice == null || body.costPrice == null || !body.supplierName) {
      return c.json({ success: false, action: 'updated', message: 'Missing required fields: eanUpc, name, sellPrice, costPrice, supplierName' }, 400)
    }

    // Validate quantityOnHand if provided
    if (body.quantityOnHand != null && (!Number.isInteger(body.quantityOnHand) || body.quantityOnHand < 0)) {
      return c.json({ success: false, action: 'updated', message: 'quantityOnHand must be a non-negative integer' }, 400)
    }

    const result = await importProduct(body)

    if (!result.success) {
      return c.json(result, 422)
    }

    return c.json(result, 200)
  } catch (err) {
    console.error('[POST /product-finder/import] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ success: false, action: 'updated', message: `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}` }, 500)
  }
})

// ============================================================================
// GET /auth/status — Authentication status (legacy endpoint)
// ============================================================================

productFinderRoutes.get('/auth/status', (c) => {
  const status = getAuthStatus()
  return c.json(status)
})

// ============================================================================
// GET /kruitbosch/detail?ean=XXX — Kruitbosch product detail endpoint
// ===========================================================================

productFinderRoutes.get('/kruitbosch/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getKruitboschDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in Kruitbosch catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/kruitbosch/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

// ============================================================================
// GET /gransier/detail?ean=XXX — Gransier product detail endpoint
// ===========================================================================

productFinderRoutes.get('/gransier/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getGransierDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in Gransier catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/gransier/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

// ============================================================================
// GET /dst/detail?ean=XXX — DST product detail endpoint
// ===========================================================================

productFinderRoutes.get('/dst/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getDstDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in DST catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/dst/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

export default productFinderRoutes

export const kruitboschProducts = sqliteTable('kruitbosch_products', {
  id: text('id').primaryKey(),
  eanUpc: text('ean_upc').notNull().unique(),
  itemNumber: text('item_number'),
  brand: text('brand'),
  model: text('model'),
  name: text('name').notNull(),
  description: text('description'),
  costPriceNet: integer('cost_price_net', { mode: 'number' }), // ex-tax cents (from Inkoop ÷ 1.21 × 100)
  sellPriceNet: integer('sell_price_net', { mode: 'number' }).notNull(), // ex-tax cents (from Verkoopprijs ÷ 1.21 × 100)
  vatRateBasisPoints: integer('vat_rate_basis_points').notNull().default(2100),
  imageUrl: text('image_url'),
  category: text('category'),
  color: text('color'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
}, (table) => ({
  eanIdx: index('kruitbosch_products_ean_idx').on(table.eanUpc),
  nameBrandIdx: index('kruitbosch_products_name_brand_idx').on(table.name, table.brand),
}))

export type KruitboschProduct = typeof kruitboschProducts.$inferSelect
export type NewKruitboschProduct = typeof kruitboschProducts.$inferInsert

// ============================================================================
// SUPPLIER & INVENTORY — Internal Procurement and Stock Audit (continued)
// ============================================================================

/** Audit trail for all inventory changes */
export const stockMovements = sqliteTable('stock_movements', {
  id: text('id').primaryKey(),
  partId: text('part_id').notNull().references(() => parts.id),
  quantityDelta: integer('quantity_delta', { mode: 'number' }).notNull(), // positive or negative
  reason: text('reason', { enum: ['sale', 'void', 'order_receive', 'manual_correction', 'backorder_receive', 'repair_use', 'return', 'waste', 'initial_stock', 'adjustment'] }).notNull(),
  referenceType: text('reference_type'), // e.g. 'sale', 'supplier_order_line'
  referenceId: text('reference_id'), // ID of source operation
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  partIdIdx: index('stock_movements_part_id_idx').on(table.partId),
  reasonIdx: index('stock_movements_reason_idx').on(table.reason),
}))

export type StockMovement = typeof stockMovements.$inferSelect
export type NewStockMovement = typeof stockMovements.$inferInsert

// ============================================================================
// NOTIFICATIONS — Customer Messaging
// ============================================================================

/** Records created when repairs are ready, backorders arrive, etc. */
export const notifications = sqliteTable('notifications', {

/**
 * ExpandableRow — Wraps a table row with expand/collapse behavior.
 *
 * Manages its own expanded/loading/error state internally. Calls onRowToggle
 * when expansion changes so parent (SearchResultsTable) can track all expanded
 * EANs for pagination reset logic.
 *
 * Supports keyboard Enter/Space toggle, focus management (focus stays on trigger),
 * and Import button event propagation stop.
 *
 * Renders DetailCardGrid with supplier-specific field configurations in the
 * expanded section.
 */

import { useState, useCallback, useRef } from 'react'
import type { ProductDetail } from '../types.js'
import { DetailCardGrid } from './DetailCardGrid.js'
import type { DetailFieldConfig } from '../types.js'

// ── Supplier-specific field configurations ────────────────────────────────

/** Kruitbosch detail fields — color badge, VAT rate info, full description */
const KRUITBOSCH_FIELDS: DetailFieldConfig[] = [
  { key: 'color', label: 'Color', variant: 'badge', conditional: true },
  { key: 'vatRateBasisPoints' as keyof ProductDetail, label: 'VAT Rate (basis points)', render: (value) => {
    const bp = typeof value === 'number' ? value : parseInt(String(value ?? ''), 10)
    if (isNaN(bp)) return <span className="text-muted-foreground">—</span>
    return <span className="font-medium">{bp / 100}% ({bp} bps)</span>
  }, conditional: true },
  { key: 'fullDescription' as keyof ProductDetail, label: 'Full Description', render: (value) => {
    if (!value || String(value).trim() === '') return <span className="text-muted-foreground">—</span>
    return <p className="leading-relaxed whitespace-pre-wrap">{String(value)}</p>
  }, conditional: true }
]

/** Gransier detail fields — color badge, VAT rate info, full description */
const GRANSIER_FIELDS: DetailFieldConfig[] = [
  { key: 'color', label: 'Color', variant: 'badge', conditional: true },
  { key: 'vatRateBasisPoints' as keyof ProductDetail, label: 'VAT Rate (basis points)', render: (value) => {
    const bp = typeof value === 'number' ? value : parseInt(String(value ?? ''), 10)
    if (isNaN(bp)) return <span className="text-muted-foreground">—</span>
    return <span className="font-medium">{bp / 100}% ({bp} bps)</span>
  }, conditional: true },
  { key: 'fullDescription' as keyof ProductDetail, label: 'Full Description', render: (value) => {
    if (!value || String(value).trim() === '') return <span className="text-muted-foreground">—</span>
    return <p className="leading-relaxed whitespace-pre-wrap">{String(value)}</p>
  }, conditional: true }
]

/** DST detail fields — status, packaging, weight, classification */
const DST_FIELDS: DetailFieldConfig[] = [
  { key: 'status', label: 'Status', variant: 'badge' },
  { key: 'minimumOrderAmount', label: 'Minimum Order Amount' },
  { key: 'unitsInPackaging', label: 'Units in Packaging' },
  { key: 'netWeight', label: 'Net Weight (kg)', variant: 'weight' },
  { key: 'grossWeight', label: 'Gross Weight (kg)', variant: 'weight' },
  { key: 'keywordDescription', label: 'Classification' },
  { key: 'productGroupDescription', label: 'Product Group' },
  { key: 'vatRate', label: 'VAT Rate' },
  { key: 'longDescription', label: 'Long Description' }
]

interface ExpandableRowProps {
  /** The row content to render as the clickable trigger */
  children: React.ReactNode
  /** Unique EAN identifier for this row (used for detail fetching) */
  ean: string
  /** Async function that fetches product detail data by EAN */
  fetchDetail: (ean: string) => Promise<ProductDetail>
  /** Callback when Import button is clicked */
  onImport?: (ean: string) => void
  /** Supplier name — used to select the correct field configuration for rendering */
  supplierName?: string
}

export function ExpandableRow({ children: rowContent, ean, fetchDetail, onImport, supplierName }: ExpandableRowProps) {
  const [expanded, setExpanded] = useState(false)
  const [detail, setDetail] = useState<ProductDetail | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  // Track whether we've already fetched detail to avoid redundant calls
  const hasFetchedRef = useRef(false)

  const fetchAndSetDetail = useCallback(async (targetEan: string) => {
    setLoading(true)
    setError(null)
    try {
      const result = await fetchDetail(targetEan)
      setDetail(result)
      hasFetchedRef.current = true
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)))
    } finally {
      setLoading(false)
    }
  }, [fetchDetail, hasFetchedRef])

  const handleToggle = useCallback(() => {
    if (!expanded) {
      setExpanded(true)
      // Fetch detail only on first expansion
      if (!hasFetchedRef.current) {
        void fetchAndSetDetail(ean)
      }
    } else {
      setExpanded(false)
    }
  }, [expanded, ean, hasFetchedRef, fetchAndSetDetail])

  const handleRetry = useCallback(() => {
    void fetchAndSetDetail(ean)
  }, [ean, fetchAndSetDetail])

  const handleImportClick = useCallback((e: React.MouseEvent) => {
    // Stop propagation so clicking Import doesn't trigger row expansion
    e.stopPropagation()
    onImport?.(ean)
  }, [onImport, ean])

  // Select field configuration based on supplier
  const fields = supplierName === 'Gransier'
    ? GRANSIER_FIELDS
    : supplierName === 'Kruitbosch'
      ? KRUITBOSCH_FIELDS
      : DST_FIELDS

  return (
    <>
      {/* Trigger row */}
      <tr
        onClick={handleToggle}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleToggle() } }}
        tabIndex={0}
        role="row"
        aria-expanded={expanded}
        className={`border-b hover:bg-muted/20 transition-colors cursor-pointer ${expanded ? 'bg-muted/30 expanded-row' : ''}`}
      >
        {rowContent}
        <td className="px-4 py-2 text-center">
          <button
            onClick={handleImportClick}
            disabled={loading}
            className="px-3 py-1 text-xs font-medium bg-primary text-primary-foreground rounded hover:bg-primary/90 disabled:opacity-50 transition-colors"
          >
            Import
          </button>
        </td>
      </tr>

      {/* Expanded detail section */}
      {expanded && (
        <tr className="border-b">
          <td colSpan={11} className="px-4 py-3 bg-muted/10">
            {loading && !error && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <svg
                  className="animate-spin h-4 w-4"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
                  />
                </svg>
                <span>Loading details...</span>
              </div>
            )}

            {error && (
              <div className="flex items-center gap-3 p-3 bg-red-50 border border-red-200 rounded-md text-sm">
                <span className="text-red-700 font-medium">Error loading details</span>
                <button
                  onClick={(e) => { e.stopPropagation(); handleRetry() }}
                  className="px-3 py-1 text-xs font-medium bg-red-600 text-white rounded hover:bg-red-700 transition-colors"
                >
                  Retry
                </button>
              </div>
            )}

            {!loading && !error && detail && (
              <DetailCardGrid detail={detail} fields={fields} />
            )}
          </td>
        </tr>
      )}
    </>
  )
}

