import { describe, it, expect } from 'vitest'
import { render, screen } from '@testing-library/react'
import { DetailCardGrid } from '../DetailCardGrid.js'
import type { ProductDetail, DetailFieldConfig } from '../../types.js'

// Mock console.error to suppress React warnings in tests
vi.spyOn(console, 'error').mockImplementation(() => {})

const mockDetail: ProductDetail = {
  eanUpc: '8712345678901',
  status: 'ACTIVE',
  minimumOrderAmount: 10,
  unitsInPackaging: 1,
  netWeight: 0.25,
  grossWeight: 0.35,
  keywordDescription: 'Schijfremmen',
  productGroupDescription: 'Hydraulische schijfremmen',
  vatRate: '21%',
  longDescription: 'Shimano BL-MT200 disc brake for reliable stopping power'
}

const defaultFields: DetailFieldConfig[] = [
  { key: 'status', label: 'Status', variant: 'badge' },
  { key: 'keywordDescription', label: 'Classification' },
  { key: 'productGroupDescription', label: 'Product Group' },
  { key: 'netWeight', label: 'Net Weight (kg)', variant: 'weight' },
  { key: 'grossWeight', label: 'Gross Weight (kg)', variant: 'weight' },
  { key: 'unitsInPackaging', label: 'Units in Packaging' },
  { key: 'vatRate', label: 'VAT Rate' },
  { key: 'longDescription', label: 'Description' }
]

describe('DetailCardGrid', () => {
  it('renders all configured fields as cards', () => {
    render(<DetailCardGrid detail={mockDetail} fields={defaultFields} />)

    expect(screen.getByText('Status')).toBeInTheDocument()
    expect(screen.getByText('ACTIVE')).toBeInTheDocument()
    expect(screen.getByText('Classification')).toBeInTheDocument()
    expect(screen.getByText('Schijfremmen')).toBeInTheDocument()
    expect(screen.getByText('Net Weight (kg)')).toBeInTheDocument()
    // Weight variant renders with 'kg' suffix
    expect(screen.getByText(/0\.25/)).toBeInTheDocument()
  })

  it('renders status as a badge', () => {
    render(<DetailCardGrid detail={mockDetail} fields={defaultFields} />)

    const statusBadge = screen.getByText('ACTIVE')
    // Badge styling: green background, rounded text
    expect(statusBadge.closest('.inline-flex')).toBeInTheDocument()
  })

  it('renders price values with highlight styling', () => {
    const priceDetail = {
      eanUpc: '8712345678901',
      recommendedRetailPriceGross: 25.00,
      grossPurchasePriceGross: 15.00
    } as ProductDetail

    const fieldsWithPrices: DetailFieldConfig[] = [
      { key: 'recommendedRetailPriceGross' as keyof ProductDetail, label: 'Retail Price', variant: 'price-highlight' },
      { key: 'grossPurchasePriceGross' as keyof ProductDetail, label: 'Purchase Price', variant: 'price-highlight' }
    ]

    render(<DetailCardGrid detail={priceDetail} fields={fieldsWithPrices} />)

    expect(screen.getByText('€25.00')).toBeInTheDocument()
    expect(screen.getByText('€15.00')).toBeInTheDocument()
  })

  it('hides conditional fields when value is null/empty', () => {
    const partialDetail: ProductDetail = {
      eanUpc: '8712345678901',
      status: 'ACTIVE'
      // keywordDescription, productGroupDescription are missing
    }

    render(<DetailCardGrid detail={partialDetail} fields={defaultFields} />)

    expect(screen.getByText('Status')).toBeInTheDocument()
    expect(screen.queryByText('Schijfremmen')).not.toBeInTheDocument()
  })

  it('renders custom field values via render function', () => {
    const customFields: DetailFieldConfig[] = [
      {
        key: 'status',
        label: 'Status Override',
        variant: 'badge',
        render: (value) => <span data-testid="custom-render">Custom: {String(value)}</span>
      }
    ]

    render(<DetailCardGrid detail={mockDetail} fields={customFields} />)

    expect(screen.getByTestId('custom-render')).toHaveTextContent('Custom: ACTIVE')
  })

  it('renders weight values with kg suffix', () => {
    const weightFields: DetailFieldConfig[] = [
      { key: 'netWeight' as keyof ProductDetail, label: 'Net Weight', variant: 'weight' },
      { key: 'grossWeight' as keyof ProductDetail, label: 'Gross Weight', variant: 'weight' }
    ]

    render(<DetailCardGrid detail={mockDetail} fields={weightFields} />)

    expect(screen.getByText('0.25 kg')).toBeInTheDocument()
    expect(screen.getByText('0.35 kg')).toBeInTheDocument()
  })

  it('renders a grid layout with card structure', () => {
    render(<DetailCardGrid detail={mockDetail} fields={defaultFields} />)

    // Each field should be wrapped in a card div
    const cards = screen.getAllByRole('region')
    expect(cards.length).toBeGreaterThan(0)
  })

  it('handles numeric values that are zero', () => {
    const zeroDetail: ProductDetail = {
      eanUpc: '8712345678901',
      minimumOrderAmount: 0,
      unitsInPackaging: 0
    }

    const fields: DetailFieldConfig[] = [
      { key: 'minimumOrderAmount' as keyof ProductDetail, label: 'Min Order Amount' },
      { key: 'unitsInPackaging' as keyof ProductDetail, label: 'Units in Pack' }
    ]

    render(<DetailCardGrid detail={zeroDetail} fields={fields} />)

    // Both fields show '0' — use query to verify at least one exists
    const zeroElements = screen.queryAllByText(/\b0\b/)
    expect(zeroElements.length).toBeGreaterThanOrEqual(1)
  })

  it('renders nothing when no fields are configured', () => {
    render(<DetailCardGrid detail={mockDetail} fields={[]} />)

    // Should not crash — returns null for empty field list
    const grid = screen.queryByRole('region')
    expect(grid).not.toBeInTheDocument()
  })
})

